 43	/**
 44	 * Deterministic Flight Recorder for Agentic Code Execution
 45	 * Records prompts, thoughts, tool calls, diffs, and durable state transitions into
 46	 * append-only .flightlog archives for exact post-mortem replay and audit.
 47	 */
 48	export class FlightRecorder {
 49	  private workspace: string;
 50	  private flightId: string;
 51	  private flightLogPath: string;
 52	  private isRecording: boolean = false;
 53	  private startTime: number = Date.now();
 54	
 55	  constructor(workspace: string, flightId?: string) {
 56	    this.workspace = path.resolve(workspace);
 57	    this.flightId = flightId || `flight-${new Date().toISOString().replace(/[:.]/g, "-")}-${randomUUID().slice(0, 6)}`;
 58	    ensureGitExclude(this.workspace);
 59	    const flightsDir = path.join(this.workspace, ".nexus", "flights");
 60	    ensurePrivateDir(flightsDir);
 61	    this.flightLogPath = path.join(flightsDir, `${this.flightId}.flightlog`);
 62	  }
 63	
 64	  public getFlightId(): string {
 65	    return this.flightId;
 66	  }
 67	
 68	  public getLogPath(): string {
 69	    return this.flightLogPath;
 70	  }
 71	
 72	  public isSessionActive(): boolean {
 73	    return this.isRecording;
 74	  }
 75	
 76	  private appendEvent(type: FlightEventType, step: number | undefined, payload: Record<string, any>): FlightEvent {
 77	    // Flightlogs are durable telemetry. Sanitize the complete event before its
 78	    // only write path; a classifier failure must not fall through to plaintext
 79	    // or prevent the authorized local capability from executing.
 80	    const eventId = `evt-${randomUUID().slice(0, 8)}`;
 81	    const timestamp = new Date().toISOString();
 82	    let sanitizedPayload: Record<string, any>;
 83	    try {
 84	      sanitizedPayload = InformationFlowBoundary.getGlobalInstance().redactForTelemetry(payload);
 85	    } catch {
 86	      // Do not propagate classifier diagnostics that could echo inspected input.
 87	      return {
 88	        eventId,
 89	        timestamp,
 90	        type,
 91	        step,
 92	        payload: { recordingSkipped: true, reason: "sanitization_failed" },
 93	      };
 94	    }
 95	    const event: FlightEvent = {
 96	      eventId,
 97	      timestamp,
 98	      type,
 99	      step,
100	      payload: sanitizedPayload,
101	    };
102	    try {
103	      appendPrivateFile(this.flightLogPath, JSON.stringify(event) + "\n");
104	    } catch {
105	      // Ignore flightlog append errors in restricted environments
106	    }
107	    return event;
108	  }
109	
110	  public startSession(config: {
111	    model: string;
112	    endpoint: string;
113	    taskPrompt?: string;
114	  }): FlightManifest {
115	    this.isRecording = true;
116	    this.startTime = Date.now();
117	
118	    let initialCommit: string | undefined;
119	    let initialBranch: string | undefined;
120	
121	    try {
122	      initialCommit = execFileSync("git", ["rev-parse", "HEAD"], {
123	        cwd: this.workspace,
124	        encoding: "utf-8",
125	        stdio: ["ignore", "pipe", "ignore"],
126	      }).trim();
127	      initialBranch = execFileSync("git", ["rev-parse", "--abbrev-ref", "HEAD"], {
128	        cwd: this.workspace,
129	        encoding: "utf-8",
130	        stdio: ["ignore", "pipe", "ignore"],
131	      }).trim();
132	    } catch {}
133	
134	    const manifest: FlightManifest = {
135	      flightId: this.flightId,
136	      recordedAt: new Date().toISOString(),
137	      workspace: this.workspace,
138	      model: config.model,
139	      endpoint: config.endpoint,
140	      initialCommit,
141	      initialBranch,
142	      taskPrompt: config.taskPrompt,
143	      status: "in_progress",
144	    };
145	
146	    this.appendEvent("session_start", 0, manifest);
147	    return manifest;
148	  }
149	
150	  public recordTurnStart(step: number, taskPrompt: string): FlightEvent {
151	    return this.appendEvent("turn_start", step, { prompt: taskPrompt });
152	  }
153	
154	  public recordThought(step: number, thoughtText: string, reasoningText?: string): FlightEvent {
155	    return this.appendEvent("thought", step, {
156	      thought: thoughtText,
157	      reasoning: reasoningText,
158	    });
159	  }
160	
161	  public recordToolCall(step: number, callId: string, toolName: string, args: Record<string, any>): FlightEvent {
162	    return this.appendEvent("tool_call", step, {
163	      callId,
164	      toolName,
165	      arguments: args,
166	    });
167	  }
168	
169	  public recordToolResult(
170	    step: number,
171	    callId: string,
172	    toolName: string,
173	    success: boolean,
174	    output: string,
175	    durationMs: number,
176	    error?: string,
177	  ): FlightEvent {
178	    return this.appendEvent("tool_result", step, {
179	      callId,
180	      toolName,
181	      success,
182	      outputLength: output.length,
183	      outputSnippet: output.slice(0, 1000),
184	      durationMs,
185	      error,
186	    });
187	  }
188	
189	  public recordDurableState(step: number, state: Record<string, any>): FlightEvent {
190	    return this.appendEvent("durable_state", step, { state });
191	  }
192	
193	  public recordFileDiff(step: number, path: string, diff: string, replacements?: number): FlightEvent {
194	    return this.appendEvent("file_diff", step, {
195	      path,
196	      diffSnippet: diff.slice(0, 2000),
197	      replacements: replacements || 1,
198	    });
199	  }
200	
201	  public recordSessionEnd(summary: string, success: boolean, tokenStats?: { prompt: number; completion: number; total: number }): FlightEvent {
202	    this.isRecording = false;
203	    const durationMs = Date.now() - this.startTime;
204	    return this.appendEvent("session_end", undefined, {
205	      summary,
206	      success,
207	      durationMs,
208	      tokenStats,
209	    });
210	  }
211	
212	  public recordMiddlewareRewrite(
213	    step: number | undefined,
214	    payload: {
215	      kind: "middleware_rewrite";
216	      plugin: string;
217	      tool: string;
218	      phase: "pre" | "post";
219	      before_digest: string;
220	      after_digest: string;
221	    }
222	  ): FlightEvent {
223	    return this.appendEvent("middleware_rewrite", step, payload);
224	  }
225	}
