230	export class FlightPlayer {
231	  public static listFlights(workspace: string): FlightManifest[] {
232	    const flightsDir = path.join(path.resolve(workspace), ".nexus", "flights");
233	    if (!fs.existsSync(flightsDir)) return [];
234	
235	    const files = fs.readdirSync(flightsDir).filter((f) => f.endsWith(".flightlog"));
236	    const manifests: FlightManifest[] = [];
237	
238	    for (const file of files) {
239	      const fullPath = path.join(flightsDir, file);
240	      try {
241	        const firstLine = fs.readFileSync(fullPath, "utf-8").split("\n")[0];
242	        if (firstLine) {
243	          const parsed = JSON.parse(firstLine);
244	          if (parsed.type === "session_start" && parsed.payload) {
245	            manifests.push(parsed.payload as FlightManifest);
246	          }
247	        }
248	      } catch {}
249	    }
