  9	export function redactSecrets(text: string): string {
 10	  if (!text) return text;
 11	  let result = text;
 12	  try {
 13	    const boundary = InformationFlowBoundary.getGlobalInstance();
 14	    const redacted = boundary.redactForTelemetry(text);
 15	    if (typeof redacted === "string") {
 16	      result = redacted;
 17	    }
 18	  } catch {}
 19	  return result
 20	    .replace(/Bearer\s+[A-Za-z0-9_\-\.]{15,}/gi, "Bearer [REDACTED_TOKEN]")
 21	    .replace(/((?:proxy-)?authorization["']?\s*[:=]\s*["']?(?:basic|bearer|token)\s+["']?)[A-Za-z0-9._~+/=-]{8,}/gi, "$1[REDACTED]")
 22	    .replace(/(?:sk-|ghp_|gho_|glpat-|xoxb-|xoxp-)[A-Za-z0-9_\-]{16,}/g, "[REDACTED_KEY]")
 23	    .replace(/-----BEGIN[ A-Z0-9_-]*PRIVATE KEY-----[\s\S]*?-----END[ A-Z0-9_-]*PRIVATE KEY-----/g, "[REDACTED_PRIVATE_KEY]")
 24	    .replace(/((?:password|secret|token|api[_-]?key)["']?\s*[:=]\s*["']?)([^"' \s\n\r]{6,})(["']?)/gi, "$1[REDACTED]$3");
