468	export function transportCauseChain(err: any): TransportCause[] {
469	  const out: TransportCause[] = [];
470	  const seen = new Set<unknown>();
471	  const visit = (e: any): void => {
472	    if (!e || typeof e !== "object" || seen.has(e) || out.length >= 8) return;
473	    seen.add(e);
474	    const c: TransportCause = {};
475	    if (typeof e.name === "string") c.name = e.name;
476	    if (typeof e.code === "string") c.code = e.code;
477	    if (typeof e.errno === "number") c.errno = e.errno;
478	    if (typeof e.syscall === "string") c.syscall = e.syscall;
479	    if (typeof e.address === "string") c.address = e.address;
480	    if (typeof e.port === "number") c.port = e.port;
481	    if (typeof e.socket?.bytesWritten === "number") c.bytesWritten = e.socket.bytesWritten;
482	    if (typeof e.socket?.bytesRead === "number") c.bytesRead = e.socket.bytesRead;
483	    if (typeof e.message === "string" && e.message) c.message = redactSecrets(e.message);
484	    out.push(c);
485	    if (Array.isArray(e.errors)) for (const sub of e.errors) visit(sub);
486	    visit(e.cause);
487	  };
488	  visit(err?.cause);
489	  return out;
490	}
