    63	export function recordEvaluationReceiptIfIdentified(
    64	  tracker: CandidateTracker,
    65	  candidateIdentity: CandidateIdentity | undefined,
    66	  testsPassed: boolean,
    67	  testCommand: string,
    68	  testOutput: string,
