   112	  /**
   113	   * Loads instances from a JSON array file or JSONL line-delimited file.
   114	   */
   115	  public static loadDataset(filePath: string): SweBenchInstance[] {
   116	    const resolved = path.resolve(filePath);
   117	    if (!fs.existsSync(resolved)) {
   118	      throw new Error(`Dataset file not found: ${resolved}`);
   119	    }
   120	
   121	    const content = fs.readFileSync(resolved, "utf-8").trim();
   122	    if (!content) return [];
   123	
   124	    // Try parsing as JSON array
   125	    if (content.startsWith("[")) {
   126	      try {
   127	        return JSON.parse(content) as SweBenchInstance[];
   128	      } catch {}
   129	    }
   130	
   131	    // Parse as JSON Lines (JSONL)
   132	    const lines = content.split("\n").filter((l) => l.trim().length > 0);
   133	    const instances: SweBenchInstance[] = [];
   134	
   135	    for (let i = 0; i < lines.length; i++) {
   136	      try {
   137	        const parsed = JSON.parse(lines[i]);
   138	        if (parsed.instance_id && parsed.problem_statement) {
   139	          instances.push(parsed as SweBenchInstance);
   140	        }
   141	      } catch (err: any) {
   142	        console.warn(pc.yellow(`Warning: Skipped malformed JSONL line ${i + 1}: ${err.message}`));
   143	      }
   144	    }
   145	
   146	    return instances;
   147	  }
