  parentSpanId?: string;
  startTimeUnixNano?: string;
}

export interface GenAiInferenceOptions {
  operationName: string;
  providerName: string;
  requestModel?: string;
  parentSpanId?: string;
  attributes?: TraceAttributes;
}

export interface SpanHandle {
  readonly traceId: string;
  readonly spanId: string;
  end(options?: { status?: TraceStatus; attributes?: TraceAttributes; endTimeUnixNano?: string }): boolean;
}

const KIND: Record<NonNullable<SpanOptions["kind"]>, number> = {
  internal: 1,
  server: 2,
  client: 3,
  producer: 4,
  consumer: 5,
};
const SESSION_ID = /^[A-Za-z0-9._-]{1,160}$/;
const ID = /^[a-f0-9]+$/;
const DEPRECATED_GENAI_ATTRIBUTES = new Set([
  "gen_ai.system",
  "gen_ai.prompt",
  "gen_ai.completion",
  "gen_ai.input.messages",
  "gen_ai.output.messages",
  "gen_ai.usage.prompt_tokens",
  "gen_ai.usage.completion_tokens",
]);

function nowUnixNano(): string {
  return (BigInt(Date.now()) * 1_000_000n).toString();
}

function randomHex(bytes: number): string {
  return randomBytes(bytes).toString("hex");
}

function otelAttributes(attributes: TraceAttributes): Array<{ key: string; value: Record<string, unknown> }> {
  return Object.entries(attributes).map(([key, value]) => {
    const val = Array.isArray(value)
      ? { arrayValue: { values: value.map((entry) => typeof entry === "string" ? { stringValue: entry } : typeof entry === "boolean" ? { boolValue: entry } : { intValue: String(entry) }) } }
      : typeof value === "string"
        ? { stringValue: value }
        : typeof value === "boolean"
          ? { boolValue: value }
          : Number.isInteger(value)
            ? { intValue: String(value) }
            : { doubleValue: value };
    return { key, value: val };
  });
}

function privateDirectory(dir: string, home: string): void {
  const relative = path.relative(home, dir);
  if (!relative || relative.startsWith(`..${path.sep}`) || relative === ".." || path.isAbsolute(relative)) {
    throw new Error("Trace directory escapes home directory");
  }
  const homeStat = fs.lstatSync(home);
  if (!homeStat.isDirectory() || homeStat.isSymbolicLink()) throw new Error("Trace home is not a real directory");
  let current = home;
  for (const segment of relative.split(path.sep).filter(Boolean)) {
    current = path.join(current, segment);
    let created = false;
    try {
      fs.mkdirSync(current, { mode: 0o700 });
      created = true;
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code !== "EEXIST") throw error;
    }
    const stat = fs.lstatSync(current);
    if (!stat.isDirectory() || stat.isSymbolicLink()) throw new Error("Trace directory is not a real directory");
    if (created) fs.chmodSync(current, 0o700);
  }
}

/** Writes one OTLP/JSON file-exporter envelope per completed span. */
export class LocalTraceRecorder {
  readonly traceId: string;
  readonly filePath: string;
  private readonly homeDir: string;
  private readonly redact: <T>(value: T) => T;
  private readonly serviceName: string;

  constructor(options: LocalTraceOptions) {
    if (!SESSION_ID.test(options.sessionId)) throw new Error("Invalid trace session id");
    const home = fs.realpathSync(path.resolve(options.homeDir ?? os.homedir()));
    this.homeDir = home;
    this.filePath = path.join(home, ".local", "share", "nexus", "traces", options.sessionId, "trace.jsonl");
    this.traceId = randomHex(16);
    this.redact = options.redact ?? ((value) => new InformationFlowBoundary().redactForTelemetry(value));
    this.serviceName = options.serviceName ?? "nexus-code";
  }

  startSpan(options: SpanOptions): SpanHandle {
    const spanId = randomHex(8);
    const startTimeUnixNano = options.startTimeUnixNano ?? nowUnixNano();
    let ended = false;
    return {
      traceId: this.traceId,
      spanId,
      end: (endOptions = {}) => {
        if (ended) return false;
        ended = true;
        if (!ID.test(spanId) || (options.parentSpanId && !/^[a-f0-9]{16}$/.test(options.parentSpanId))) return false;
        const attributes = { ...(options.attributes ?? {}), ...(endOptions.attributes ?? {}) };
        let safe: { name: string; attributes: TraceAttributes };
        try {
          safe = this.redact({ name: options.name, attributes });
        } catch {
          return false;
        }
        const span = {
          traceId: this.traceId,
          spanId,
          ...(options.parentSpanId ? { parentSpanId: options.parentSpanId } : {}),
          name: safe.name,
          kind: KIND[options.kind ?? "internal"],
          startTimeUnixNano,
          endTimeUnixNano: endOptions.endTimeUnixNano ?? nowUnixNano(),
          attributes: otelAttributes(safe.attributes),
          status: { code: endOptions.status === "error" ? 2 : endOptions.status === "ok" ? 1 : 0 },
        };
        const record = JSON.stringify({
          resourceSpans: [{
            resource: { attributes: [{ key: "service.name", value: { stringValue: this.serviceName } }] },
            scopeSpans: [{ scope: { name: "nexus-code", version: "1.1.0" }, spans: [span] }],
          }],
        });
        try {
          privateDirectory(path.dirname(this.filePath), this.homeDir);
          try {
            const existing = fs.lstatSync(this.filePath);
            if (!existing.isFile() || existing.isSymbolicLink() || existing.nlink !== 1) return false;
          } catch (error) {
            if ((error as NodeJS.ErrnoException).code !== "ENOENT") return false;
          }
          const fd = fs.openSync(this.filePath, fs.constants.O_WRONLY | fs.constants.O_APPEND | fs.constants.O_CREAT | (fs.constants.O_NOFOLLOW ?? 0), 0o600);
          try {
            const stat = fs.fstatSync(fd);
            if (!stat.isFile() || stat.nlink !== 1) return false;
            fs.fchmodSync(fd, 0o600);
            fs.writeSync(fd, `${record}\n`, undefined, "utf8");
          } finally {
            fs.closeSync(fd);
          }
          return true;
        } catch {
          return false;
        }
      },
    };
  }

  /** Creates a client inference span with the current GenAI convention's required attributes. */
  startGenAiInference(options: GenAiInferenceOptions): SpanHandle {
    if (!options.operationName || !options.providerName) throw new Error("GenAI inference requires operationName and providerName");
    const deprecated = Object.keys(options.attributes ?? {}).find((key) => DEPRECATED_GENAI_ATTRIBUTES.has(key));
    if (deprecated) {
      const replacement = deprecated === "gen_ai.system" ? "; use gen_ai.provider.name" : deprecated === "gen_ai.usage.prompt_tokens" ? "; use gen_ai.usage.input_tokens" : deprecated === "gen_ai.usage.completion_tokens" ? "; use gen_ai.usage.output_tokens" : "";
      throw new Error(`${deprecated} is deprecated${replacement}`);
    }
    const attributes: TraceAttributes = {
      "gen_ai.operation.name": options.operationName,
      "gen_ai.provider.name": options.providerName,
      ...options.attributes,
    };
    if (options.requestModel) attributes["gen_ai.request.model"] = options.requestModel;
    return this.startSpan({
      name: `${options.operationName} ${options.requestModel ?? ""}`.trim(),
      kind: "client",
      parentSpanId: options.parentSpanId,
      attributes,
    });
  }
}
import { test } from "node:test";
import assert from "node:assert/strict";
import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import { InformationFlowBoundary } from "../src/core/egress.js";
import { LocalTraceRecorder } from "../src/core/trace.js";

function home(): string {
  return fs.mkdtempSync(path.join(os.tmpdir(), "nexus-trace-test-"));
}

test("writes nested spans as OTLP/JSON under the per-session traces directory", () => {
  const isolatedHome = home();
  const recorder = new LocalTraceRecorder({ sessionId: "session_test-1", homeDir: isolatedHome });
  const turn = recorder.startSpan({ name: "nexus.agent.turn", attributes: { "nexus.turn.outcome": "SUCCESS" } });
  const inference = recorder.startGenAiInference({
    operationName: "chat",
    providerName: "openai",
    requestModel: "test-model",
    parentSpanId: turn.spanId,
  });
  assert.equal(inference.end({ status: "ok", attributes: { "gen_ai.usage.input_tokens": 12 } }), true);
  assert.equal(turn.end(), true);
  assert.equal(turn.end(), false);

  assert.equal(recorder.filePath, path.join(isolatedHome, ".local/share/nexus/traces/session_test-1/trace.jsonl"));
  const lines = fs.readFileSync(recorder.filePath, "utf8").trim().split("\n").map((line) => JSON.parse(line));
  assert.equal(lines.length, 2);
  for (const record of lines) {
    const spans = record.resourceSpans[0].scopeSpans[0].spans;
    assert.match(spans[0].traceId, /^[a-f0-9]{32}$/);
    assert.match(spans[0].spanId, /^[a-f0-9]{16}$/);
    assert.match(spans[0].startTimeUnixNano, /^\d+$/);
    assert.match(spans[0].endTimeUnixNano, /^\d+$/);
  }
  const inferenceSpan = lines[0].resourceSpans[0].scopeSpans[0].spans[0];
  assert.equal(inferenceSpan.kind, 3);
  assert.equal(inferenceSpan.parentSpanId, turn.spanId);
  const attrs = Object.fromEntries(inferenceSpan.attributes.map((attribute: any) => [attribute.key, attribute.value]));
  assert.equal(attrs["gen_ai.operation.name"].stringValue, "chat");
  assert.equal(attrs["gen_ai.provider.name"].stringValue, "openai");
  assert.equal(attrs["gen_ai.request.model"].stringValue, "test-model");
  assert.equal(attrs["gen_ai.usage.input_tokens"].intValue, "12");
  assert.equal(fs.statSync(recorder.filePath).mode & 0o777, 0o600);
});

test("redacts synthetic credentials before writing and refuses deprecated provider attribute", () => {
  const isolatedHome = home();
  const secret = "synthetic_trace_secret_abc123";
  const boundary = new InformationFlowBoundary({ explicitSecrets: [secret] });
  const recorder = new LocalTraceRecorder({ sessionId: "session_redact", homeDir: isolatedHome, redact: (value) => boundary.redactForTelemetry(value) });
  const span = recorder.startGenAiInference({
    operationName: "chat",
    providerName: "openai",
    attributes: { "nexus.test.value": secret },
  });
  assert.equal(span.end(), true);
  const stored = fs.readFileSync(recorder.filePath, "utf8");
  assert.equal(stored.includes(secret), false);
  assert.match(stored, /REDACTED/);
  assert.throws(() => recorder.startGenAiInference({
    operationName: "chat",
    providerName: "openai",
    attributes: { "gen_ai.system": "openai" },
  }), /deprecated/);
  for (const deprecated of ["gen_ai.prompt", "gen_ai.completion", "gen_ai.input.messages", "gen_ai.output.messages", "gen_ai.usage.prompt_tokens", "gen_ai.usage.completion_tokens"]) {
    assert.throws(() => recorder.startGenAiInference({
      operationName: "chat",
      providerName: "openai",
      attributes: { [deprecated]: "legacy" },
    }), /deprecated/);
  }
  assert.throws(() => recorder.startGenAiInference({ operationName: "", providerName: "openai" }), /requires/);
});

test("returns false without throwing when redaction or persistence fails", () => {
  const isolatedHome = home();
  const failedRedaction = new LocalTraceRecorder({ sessionId: "session_redaction_failure", homeDir: isolatedHome, redact: () => { throw new Error("synthetic failure"); } });
  assert.equal(failedRedaction.startSpan({ name: "safe" }).end(), false);
  assert.equal(fs.existsSync(failedRedaction.filePath), false);

  const blockedPath = new LocalTraceRecorder({ sessionId: "session_blocked", homeDir: isolatedHome });
  const traces = path.dirname(path.dirname(blockedPath.filePath));
  fs.mkdirSync(traces, { recursive: true });
  fs.symlinkSync(os.tmpdir(), path.join(traces, "session_blocked"));
  assert.equal(blockedPath.startSpan({ name: "safe" }).end(), false);

  const linkedPath = new LocalTraceRecorder({ sessionId: "session_hardlink", homeDir: isolatedHome });
  fs.mkdirSync(path.dirname(linkedPath.filePath), { recursive: true });
  const outsideFile = path.join(isolatedHome, "outside.jsonl");
  fs.writeFileSync(outsideFile, "preserve\n", { mode: 0o600 });
  fs.linkSync(outsideFile, linkedPath.filePath);
  assert.equal(linkedPath.startSpan({ name: "safe" }).end(), false);
  assert.equal(fs.readFileSync(outsideFile, "utf8"), "preserve\n");
});

test("rejects unsafe session identifiers before constructing a trace path", () => {
  assert.throws(() => new LocalTraceRecorder({ sessionId: "../../outside" }), /Invalid trace session id/);
});
# SPEC-OBSERVABILITY: Local-First OpenTelemetry Tracing & Evaluation Layer

| | |
|---|---|
| Status | Proposed / Specification |
| Target Milestone | Nexus Code `v1.1.0` |
| Primary Requirements | `REQ-OPS-101`, `REQ-DX-105`, `REQ-EVL-101`, `REQ-SEC-111` |
| Parent Strategy | [LANGSMITH_REVIEW.md](./LANGSMITH_REVIEW.md), [ROADMAP.md](./ROADMAP.md) |
| Affected Components | `cli/src/core/trace.ts`, `cli/src/core/agent.ts`, `eval/`, `cli/src/index.ts` |

---

## 1. Objective

Provide Nexus Code with a structured, standards-compliant observability and evaluation layer that enables:
1. **Hierarchical Execution Visibility:** Real-time and retrospective inspection of agent turns, model calls, tool executions, and context compaction.
2. **Local-First Privacy:** Zero network egress of prompt text, source code, or credentials by default.
3. **OpenTelemetry Interoperability:** OTLP/JSON-compatible traces using the current OpenTelemetry GenAI client-inference conventions, allowing local inspection and later pluggable export.
4. **Structured Evaluation:** Versioned datasets with strict separation of agent stimulus (`examples.jsonl`) from evaluation assertions (`oracles.jsonl`).
5. **Deterministic Replay:** Containerized reproduction of tool call sequences without re-invoking inference models.

---

## 2. OpenTelemetry GenAI Span Architecture

Every agent execution is modeled as a tree of OpenTelemetry-compatible spans:

```
[Trace: Agent Session (Thread)]
 └── [Span: Turn 1 (Root)]
      ├── [Span: Model Inference Request] (gen_ai.provider.name=openai, gen_ai.request.model=qwen2.5-coder)
      ├── [Span: Tool Invocation: read_file] (agent.tool.name=read_file, path=cli/src/agent.ts)
      ├── [Span: Tool Invocation: run_command] (agent.tool.name=run_command, cmd=npm test)
      │    └── [Event: Process Spawned] (pid=45812)
      │    └── [Event: Process Exited] (exit_code=0)
      ├── [Span: Context Compaction] (nexus.compaction.reason=token_ceiling)
      └── [Span: Model Inference Request] (gen_ai.provider.name=openai, gen_ai.request.model=qwen2.5-coder)
```

### 2.1 Span Specifications

#### Turn Span (Root)
- **Name:** `nexus.agent.turn`
- **Kind:** `INTERNAL`
- **Attributes:**
  - `nexus.turn.id`: UUIDv4
  - `nexus.session.id`: Current session UUID
  - `nexus.turn.objective`: User prompt / objective string (redacted)
  - `nexus.turn.step_count`: Total steps executed
  - `nexus.turn.outcome`: `SUCCESS` | `FAILED` | `CANCELLED` | `PERSISTENCE_FAILED`
  - `nexus.turn.duration_ms`: Wall-clock execution time in milliseconds

#### Model Inference Span
- **Name:** `{gen_ai.operation.name} {gen_ai.request.model}` (for example, `chat qwen2.5-coder`)
- **Kind:** `CLIENT`
- **Attributes (OTel Standard):**
  - `gen_ai.operation.name`: Required operation name, such as `chat` or `text_completion`
  - `gen_ai.provider.name`: Required provider classification (for example `openai`, `anthropic`, or a documented custom provider)
  - `gen_ai.request.model`: Required when available from the request
  - `gen_ai.response.model`: Actual model returned by endpoint
  - `gen_ai.request.temperature`: Temperature float
  - `gen_ai.request.max_tokens`: Configured output token limit
  - `gen_ai.usage.input_tokens`: Measured or estimated prompt tokens
  - `gen_ai.usage.output_tokens`: Measured completion tokens
  - `gen_ai.response.finish_reasons`: `["stop"]` | `["tool_calls"]` | `["length"]`
  - `nexus.inference.endpoint`: Base URL of inference endpoint (with credentials stripped)
  - `nexus.inference.token_accounting_mode`: `STRICT_MEASURED` | `CLIENT_ESTIMATE`

The semantic-convention source used for WP-1101 is the OpenTelemetry GenAI conventions repository, [client inference](https://github.com/open-telemetry/semantic-conventions-genai/blob/main/docs/gen-ai/client-inference.md), checked 2026-10-31. That document is marked **Development** and its current required client span attributes are `gen_ai.operation.name` and `gen_ai.provider.name`; `gen_ai.request.model` is conditionally required when available. Record the revision or release tag used when the release implementation is frozen; do not describe the moving `main` document as a versioned stable release. The general OpenTelemetry semantic-conventions registry identifies itself as 1.44.0, and marks moved legacy GenAI fields as deprecated. In particular, do not emit `gen_ai.system` (use `gen_ai.provider.name`), `gen_ai.usage.prompt_tokens` (use `gen_ai.usage.input_tokens`), or `gen_ai.usage.completion_tokens` (use `gen_ai.usage.output_tokens`). The legacy `gen_ai.prompt`, `gen_ai.completion`, `gen_ai.input.messages`, and `gen_ai.output.messages` fields are also deprecated or moved; this design omits them both for migration compatibility and because their contents can contain sensitive prompt/output data. See the [GenAI registry migration entries](https://opentelemetry.io/docs/specs/semconv/registry/attributes/gen-ai/) and the [registry version](https://opentelemetry.io/docs/specs/semconv/).

#### Tool Execution Span
- **Name:** `nexus.tool.execute`
- **Kind:** `INTERNAL`
- **Attributes:**
  - `agent.tool.name`: Registered tool name (e.g. `run_command`, `read_file`, `edit_file`)
  - `agent.tool.parameters`: JSON-stringified sanitized parameters
  - `nexus.tool.exit_code`: Numeric exit code (for commands/processes)
  - `nexus.tool.sandbox`: `bwrap` | `path_confined` | `none`
  - `nexus.tool.duration_ms`: Execution duration in milliseconds
  - `nexus.tool.error`: Error message if tool failed

#### Compaction Span
- **Name:** `nexus.context.compaction`
- **Kind:** `INTERNAL`
- **Attributes:**
  - `nexus.compaction.pre_tokens`: Token count prior to compaction
  - `nexus.compaction.post_tokens`: Token count after compaction
  - `nexus.compaction.tokens_freed`: Token delta
  - `nexus.compaction.preserved_items_count`: Count of active messages retained
  - `nexus.compaction.durable_fsync_ms`: Time taken for ordered fsync barrier

---

## 3. Credential Redaction & Privacy Pipeline (REQ-DX-105 / CRED003)

Before any span or event is written to disk or memory:
1. **Header Sanitization:** Strip all `Authorization: Bearer ...`, `X-Api-Key: ...`, and `Cookie: ...` headers.
2. **Regex Credential Scanners:** Match and mask common key formats:
   - OpenAI (`sk-[A-Za-z0-9]{32,}` → `sk-...[REDACTED]`)
   - Anthropic (`sk-ant-[A-Za-z0-9]{32,}` → `sk-ant-...[REDACTED]`)
   - GitHub Tokens (`ghp_[A-Za-z0-9]{36}` → `ghp_...[REDACTED]`)
   - Private Keys (`-----BEGIN [A-Z ]+ PRIVATE KEY-----` → `[REDACTED PRIVATE KEY]`)
3. **Filesystem Path Preservation:** As specified in `REQ-DX-104`, absolute paths (`/home/user/workspace/file.ts`) are **exempt from redaction** to preserve diagnostic and replay capability.

---

## 4. Local Storage Format (`trace.jsonl`)

Traces are stored per session in newline-delimited JSON (`ndjson`):
```text
~/.local/share/nexus/
├── sessions/
│   └── <session-id>/
│       ├── session.json      # Session state and history
│       └── journal.log       # Durable transaction log
└── traces/
    └── <session-id>/
        └── trace.jsonl       # OTel span records (v1.1+)
```

Each line in `trace.jsonl` is a self-contained OpenTelemetry Span JSON record conforming to the OTLP/JSON schema. This allows external tools (`jq`, Python scripts, OTel collector file receivers) to read and parse traces without custom libraries.

The earlier draft placed `trace.jsonl` beside session state under `sessions/<session-id>/`. WP-1101 follows release gate G1.1-1, which explicitly requires traces under `~/.local/share/nexus/traces/`; the diagram above is the reconciled normative path. Session state remains under `sessions/`, and trace files are stored once under `traces/`.

---

## 5. Structured Evaluation Dataset Format (`eval/datasets/`)

Nexus v1.1.0 replaces ad-hoc task fixtures with structured, versioned evaluation datasets:

```
eval/datasets/
└── core-regression-v1/
    ├── manifest.json         # Metadata, version, and splits
    ├── examples.jsonl        # Inputs given to agent

