    if (process.env.NEXUS_DEBUG === "1") console.log(pc.dim(`\nwork step ${step}${Number.isFinite(maxSteps) ? `/${maxSteps}` : ""}`));
  }

  startSpinner(text: string): void {
    this.spinner = ora({
