    const output = formatReplTurnError(new Error(`turn failed with ${secret}`));
    assert.match(output, /diagnostic suppressed/);
    assert.equal(output.includes(secret), false);
  } finally {
    InformationFlowBoundary.setGlobalInstance(original);
  }
});
