    journalEntry.state = "complete";
    journalEntry.updatedAt = new Date().toISOString();
    writeJournal(prefix, journalEntry);

    return {
      success: true,
      previousVersion: installed.version,
      newVersion: targetVersion,
      installedPath: versionDir,
      binPath: linkPath,
