export async function downloadFile(
  url: string,
  destPath: string,
  signal?: AbortSignal,
  timeoutMs = 60000,
  maxHops = 5
): Promise<void> {
  let currentUrl = url;
  let hops = 0;
  let connectionResets = 0;

  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(new Error(`Download timed out after ${timeoutMs}ms`)), timeoutMs);
  if (signal) {
    signal.addEventListener("abort", () => controller.abort(signal.reason), { once: true });
  }

  try {
    while (hops <= maxHops) {
      if (!validateDownloadUrl(currentUrl)) {
        throw new Error(`Disallowed download origin or invalid URL (${safeDownloadOrigin(currentUrl)})`);
      }

      const headers: Record<string, string> = { "User-Agent": "nexus-upgrade" };
      const token = process.env.GITHUB_TOKEN || process.env.GH_TOKEN;
      if (token && (new URL(currentUrl)).hostname === "github.com") {
        headers.Authorization = `Bearer ${token}`;
      }

      let res: Response;
      try {
        res = await fetch(currentUrl, {
          headers,
          signal: controller.signal,
          redirect: "manual",
        });
      } catch (error) {
        if (connectionResets < 1 && isDownloadConnectionReset(error)) {
          connectionResets++;
          continue;
        }
        throw error;
      }

      // Handle redirect
      if (res.status === 301 || res.status === 302 || res.status === 307 || res.status === 308) {
        const location = res.headers.get("location");
        if (!location) {
          throw new Error(`HTTP ${res.status} redirect without Location header from ${safeDownloadOrigin(currentUrl)}`);
        }
        currentUrl = new URL(location, currentUrl).toString();
        hops++;
        continue;
      }

      if (!res.ok) {
        throw new Error(`HTTP ${res.status} downloading from ${safeDownloadOrigin(currentUrl)}`);
      }

      const contentLengthHeader = res.headers.get("content-length");
      if (contentLengthHeader) {
        const contentLength = parseInt(contentLengthHeader, 10);
        if (contentLength > MAX_DOWNLOAD_BYTES) {
          throw new Error(`Download size (${contentLength} bytes) exceeds maximum allowed limit (${MAX_DOWNLOAD_BYTES} bytes)`);
        }
      }

      const fileStream = fs.createWriteStream(destPath);
      if (!res.body) {
        throw new Error(`Empty body downloading from ${safeDownloadOrigin(currentUrl)}`);
      }

      let bytesDownloaded = 0;
      const reader = res.body.getReader();

      try {
        await new Promise<void>((resolve, reject) => {
          fileStream.on("error", reject);
          fileStream.on("finish", () => resolve());
          function pump() {
            reader.read().then(({ done, value }) => {
              if (done) {
                fileStream.end();
                return;
              }
              bytesDownloaded += value.byteLength;
              if (bytesDownloaded > MAX_DOWNLOAD_BYTES) {
                reject(new Error(`Download exceeded maximum limit of ${MAX_DOWNLOAD_BYTES} bytes`));
                return;
              }
              fileStream.write(Buffer.from(value), (err) => {
                if (err) reject(err);
                else pump();
              });
            }).catch(reject);
          }
          pump();
        });
      } catch (streamErr) {
        try { fs.unlinkSync(destPath); } catch {}
        throw streamErr;
      }

      return;
    }

    throw new Error(`Too many redirects (exceeded ${maxHops} hops) while downloading`);
  } finally {
    clearTimeout(timer);
  }
}

