 83	function validatedEndpoint(input: string): { endpoint: string; origin: string } | undefined {
 84	  const endpoint = input.trim().replace(/\/+$/, "");
 85	  try {
 86	    const url = new URL(endpoint);
 87	    if ((url.protocol !== "http:" && url.protocol !== "https:") || url.username || url.password || url.search || url.hash || /[\r\n\0]/.test(endpoint)) return undefined;
 88	    return { endpoint, origin: url.origin };
 89	  } catch {
 90	    return undefined;
 91	  }
 92	}
