 99	    model: "local-model",
100	    ...(key ? { apiKey: key, credentialOrigin: origin } : { apiKey: undefined, credentialOrigin: undefined }),
101	    pinEndpoint: true,
102	    fallbackEndpoints: undefined,
103	    authorizedDisclosureOrigins: [...new Set([...(base.authorizedDisclosureOrigins ?? []), origin])],
104	  };
105	}
