113	export async function prepareLocalEndpoint(base: HarnessConfig, endpointInput: string, keyInput = "", requestId?: string): Promise<LocalEndpointPreparation> {
114	  const parsed = validatedEndpoint(endpointInput);
115	  if (!parsed) return { ok: false, message: "Use an http:// or https:// endpoint without embedded credentials, query, or fragment." };
116	  const key = validatedKey(keyInput);
117	  if (key === undefined) return { ok: false, message: "The API key must be a single value without whitespace." };
118	  const request = { cancelled: false };
119	  if (requestId) localEndpointSetupRequests.set(requestId, request);
120	  try {
121	    const models = await new LocalLlmClient(localEndpointConfig(base, parsed.endpoint, parsed.origin, key), { allowCredentialReload: false }).listModels();
122	    if (request.cancelled) return { ok: false, cancelled: true, message: "Local endpoint setup was cancelled." };
123	    const available = models.filter((model) => chatModel(APPLIANCE, model) && /^[A-Za-z0-9._:/@+-]{1,160}$/.test(model));
124	    if (available.length === 0) return { ok: false, message: "That endpoint returned no usable chat models." };
125	    activateApplianceEndpoint(parsed.endpoint, undefined, true, key || undefined);
126	    provisionalLocalEndpointRequestId = requestId;
127	    const disclosure = disclosureClass(parsed.endpoint, undefined, base.cloudRoutedOrigins);
128	    return {
129	      ok: true,
130	      message: disclosure === "cloud"
131	        ? `Cloud endpoint verified (${available.length} models found). Choosing a model will send task content to this endpoint.`
132	        : `Local endpoint verified (${available.length} models found). Choose a model to save setup.`,
133	    };
134	  } catch {
135	    if (request.cancelled) return { ok: false, cancelled: true, message: "Local endpoint setup was cancelled." };
136	    return { ok: false, message: "Could not list models from that endpoint. Check the URL and API key, then try again." };
137	  } finally {
138	    if (requestId && localEndpointSetupRequests.get(requestId) === request) localEndpointSetupRequests.delete(requestId);
139	  }
140	}
