142	/** Discover a local OpenAI-compatible endpoint, then persist only its selected URL/model and origin-scoped key. */
143	export async function connectLocalEndpoint(
144	  base: HarnessConfig,
145	  endpointInput: string,
146	  modelInput?: string,
147	  keyInput = "",
148	): Promise<LocalEndpointConnection> {
149	  const parsed = validatedEndpoint(endpointInput);
150	  if (!parsed) {
151	    return { ok: false, message: "Use an http:// or https:// endpoint without embedded credentials, query, or fragment.", models: [] };
152	  }
153	  const { endpoint, origin } = parsed;
154	  const key = validatedKey(keyInput);
155	  if (key === undefined) {
156	    return { ok: false, message: "The API key must be a single value without whitespace.", models: [] };
157	  }
158	  const config = localEndpointConfig(base, endpoint, origin, key);
159	  let models: string[];
160	  try {
161	    models = await new LocalLlmClient(config, { allowCredentialReload: false }).listModels();
162	  } catch {
163	    return { ok: false, message: "Could not list models from that endpoint. Check the URL and API key, then try again.", models: [] };
164	  }
165	  const available = models.filter((model) => chatModel(APPLIANCE, model) && /^[A-Za-z0-9._:/@+-]{1,160}$/.test(model));
166	  if (!modelInput?.trim()) {
167	    return { ok: available.length > 0, message: available.length > 0 ? "Model discovery succeeded." : "That endpoint returned no usable chat models.", models: available };
168	  }
169	  const model = modelInput.trim();
170	  if (!available.includes(model)) {
171	    return { ok: false, message: "Choose a model returned by the endpoint's model list.", models: available };
172	  }
173	  try {
174	    if (key) {
175	      if (!commitLocalEndpointSetup(endpoint, key, () => saveLocalEndpointSettings(endpoint, model))) {
176	        return { ok: false, message: "Nexus could not securely save the endpoint setup.", models: available };
177	      }
178	    } else {
179	      saveLocalEndpointSettings(endpoint, model);
180	    }
181	  } catch {
182	    return { ok: false, message: "Models were discovered, but Nexus could not securely save the endpoint setup.", models: available };
183	  }
184	  activateApplianceEndpoint(endpoint, model, false);
185	  provisionalLocalEndpointRequestId = undefined;
186	  const disclosure = disclosureClass(endpoint, undefined, base.cloudRoutedOrigins);
187	  return {
188	    ok: true,
189	    message: `${disclosure === "cloud" ? "Cloud" : "Local"} endpoint configured (${available.length} models available).${key ? " API key saved for this origin only." : " No API key was saved."}`,
190	    models: available,
191	  };
192	}
