200	export async function startSignIn(base: HarnessConfig, providerId: string, methodId: string): Promise<SignIn> {
201	  const def = providerDefinition(providerId);
202	  const method = def?.methods.find((m) => m.id === methodId);
203	  if (!def || !method || method.kind === "key") throw new Error(`${providerId} has no sign-in method '${methodId}'.`);
204	  const abort = new AbortController();
205	  const flow = await startAuthFlow(methodId, abort.signal);
206	  void openBrowser(flow.prompt.url);
207	  const done = flow.result.then(
208	    async (credential: StoredCredential) => {
209	      saveCredential(providerId, credential);
210	      try {
211	        const count = await verify(base, providerId);
212	        return { ok: true, message: `${def.label} connected (${count} models available).` };
213	      } catch (err) {
214	        return { ok: true, message: `${def.label} signed in, but listing its models failed: ${describe(err)}.` };
215	      }
216	    },
217	    (err) => ({ ok: false, message: `${def.label} sign-in failed: ${describe(err)}` }),
218	  );
219	  return { prompt: flow.prompt, done, cancel: () => { abort.abort(); flow.cancel(); } };
220	}
