122	function safeStepDetail(ok: boolean, detail: string): string {
123	  if (!ok) return detail === "Provider request failed" ? detail : "Verification failed";
124	  if (/^streamed completion received \(\d+ chars\)$/.test(detail)) return detail;
125	  if (/^echo_token tool call completed \(\d+ call\(s\)\)$/.test(detail)) return detail;
