114	  const parsed = validatedEndpoint(endpointInput);
115	  if (!parsed) return { ok: false, message: "Use an http:// or https:// endpoint without embedded credentials, query, or fragment." };
116	  const key = validatedKey(keyInput);
117	  if (key === undefined) return { ok: false, message: "The API key must be a single value without whitespace." };
118	  const request = { cancelled: false };
119	  if (requestId) localEndpointSetupRequests.set(requestId, request);
120	  try {
