200	export async function startSignIn(base: HarnessConfig, providerId: string, methodId: string): Promise<SignIn> {
201	  const def = providerDefinition(providerId);
202	  const method = def?.methods.find((m) => m.id === methodId);
203	  if (!def || !method || method.kind === "key") throw new Error(`${providerId} has no sign-in method '${methodId}'.`);
204	  const abort = new AbortController();
