215	      }
216	    },
217	    (err) => ({ ok: false, message: `${def.label} sign-in failed: ${describe(err)}` }),
218	  );
219	  return { prompt: flow.prompt, done, cancel: () => { abort.abort(); flow.cancel(); } };
