128	  start(): void {
129	    this.emit({ type: "hello", protocol: PROTOCOL_VERSION, pid: process.pid, commands: slashCatalog() });
130	    let resumed: { ok: boolean; message: string } | undefined;
131	    try {
132	      resumed = this.resume ? this.resumeSession(this.resume) : undefined;
133	    } catch (err) {
134	      resumed = { ok: false, message: `Could not resume ${this.resume}: ${redactSecrets(errorText(err))}` };
135	    }
136	    this.emitSessionState();
137	    if (resumed) this.emit({ type: "notice", text: resumed.message });
138	    if (isNexusDirPermissive()) {
139	      this.emit({ type: "notice", text: "your Nexus state is readable by other users; run `nexus doctor --fix`" });
140	    }
141	    void this.app.getAgent().probeStartupEndpoint(this.startupProbeAbort.signal).then((warning) => {
142	      if (warning && !this.shutdownPromise) {
143	        this.emit({ type: "notice", text: redactSecrets(warning) });
144	      }
145	    }).catch(() => {});
146	  }
