148	  /** Resolves once no turn is running. */
149	  async idle(): Promise<void> {
150	    while (this.activeTurn) await this.activeTurn;
151	  }
152	
153	  async handleLine(line: string): Promise<void> {
154	    if (!line.trim()) return;
155	    let command: SidecarCommand;
156	    try {
157	      command = parseCommand(line);
158	    } catch (err) {
159	      const id = err instanceof ProtocolError ? err.id : undefined;
160	      this.emit({ type: "error", ...(id ? { id } : {}), code: "BAD_REQUEST", message: (err as Error).message });
161	      return;
162	    }
163	    switch (command.type) {
164	      case "prompt.submit":
165	        this.submit(command.id, command.text);
166	        return;
167	      case "steer":
168	        this.steer(command.id, command.text);
169	        return;
170	      case "cancel":
171	        this.cancel();
172	        return;
173	      case "approve":
174	        this.resolveApproval(command.id, true, command.always);
175	        return;
176	      case "deny":
177	        this.resolveApproval(command.id, false, false);
178	        return;
179	      case "checkpoint.choice":
180	        this.resolveCheckpointChoice(command.id, command.choice);
181	        return;
182	      case "slash":
183	        this.slash(command.id, command.command, command.args);
184	        return;
185	      case "tool.detail":
186	      case "receipt":
187	        try {
188	          if (command.type === "tool.detail") this.toolDetail(command.id, command.evidence);
189	          else this.emit({ type: "receipt", id: command.id, sections: this.receipt() });
190	        } catch (err) {
191	          const message = capText(redactSecrets(stripEscapes((err as Error).message ?? String(err))));
192	          this.emit({ type: "error", id: command.id, code: "INTERNAL", message });
193	        }
194	        return;
195	      case "models.list":
196	        if (this.app.getAgent().getApprovalMode() === "read-only") {
197	          this.emit({ type: "error", id: command.id, code: "BUSY", message: "Provider discovery is disabled while the session is in read-only mode." });
198	          return;
199	        }
200	        void this.modelsList(command.id);
201	        return;
202	      case "model.select":
203	        if (this.app.getAgent().getApprovalMode() === "read-only") {
204	          this.emit({ type: "error", id: command.id, code: "BUSY", message: "Model changes are disabled while the session is in read-only mode." });
205	          return;
206	        }
207	        this.modelSelect(command.id, command.provider, command.model);
208	        return;
209	      case "provider.connect":
210	        if (this.app.getAgent().getApprovalMode() === "read-only") {
211	          this.emit({ type: "provider.result", id: command.id, provider: command.provider, success: false, message: "Provider connections are disabled while the session is in read-only mode." });
212	          return;
213	        }
214	        void this.providerConnect(command.id, command.provider, command.method, command.key, command.endpoint);
215	        return;
216	      case "provider.cancel":
217	        this.signIns.get(command.id)?.cancel();
218	        this.signIns.delete(command.id);
219	        cancelLocalEndpointSetup(command.id);
220	        return;
221	      case "provider.local-cancel":
222	        clearLocalEndpointSetup(command.id);
223	        return;
224	      case "provider.disconnect": {
225	        if (this.app.getAgent().getApprovalMode() === "read-only") {
226	          this.emit({ type: "provider.result", id: command.id, provider: command.provider, success: false, message: "Provider changes are disabled while the session is in read-only mode." });
227	          return;
228	        }
229	        const r = disconnect(command.provider);
230	        this.emit({ type: "provider.result", id: command.id, provider: command.provider, success: r.ok, message: r.message });
231	        return;
232	      }
233	      case "shutdown":
234	        await this.shutdown();
235	        return;
236	    }
237	  }
