370	  /** Reports BUSY for `id` when a turn or command is running or the sidecar is shutting down. */
371	  private rejectBusy(id: string): boolean {
372	    if (!this.shutdownPromise && !this.activeTurn) return false;
373	    const message = this.shutdownPromise ? "The sidecar is shutting down." : "A turn or command is running; cancel it or wait for its result.";
374	    this.emit({ type: "error", id, code: "BUSY", message });
