378	  /**
379	   * /compact while a turn or command runs. During an agent turn the agent holds it until the turn's next step boundary
380	   * (after the in-flight inference and its tool batch, approvals included, have settled) or the turn's end. While another
381	   * command runs, it waits here and runs as its own job afterwards. Each request is acknowledged now (notice) and gets
382	   * its outcome later (slash.result for its id). A duplicate shares the queued request's outcome; at most one request
383	   * per kind (default, --llm) waits; cancellation and shutdown end waiting requests with that outcome.
384	   */
385	  private queueCompaction(id: string, llm: boolean): void {
386	    const queued = this.app.getAgent().requestCompaction(id, llm);
387	    if (queued.status !== "no_active_turn") {
388	      this.emit({ type: "notice", text: queued.message });
389	      return;
390	    }
391	    const existing = this.pendingCompactions.find((p) => p.llm === llm);
392	    if (existing) {
393	      existing.ids.push(id);
394	      this.emit({ type: "notice", text: `A /compact${llm ? " --llm" : ""} is already waiting; this request shares its outcome.` });
395	      return;
396	    }
397	    this.pendingCompactions.push({ ids: [id], llm });
398	    this.emit({ type: "notice", text: `/compact${llm ? " --llm" : ""} queued: it runs when the current command finishes.` });
399	  }
