192	          this.emit({ type: "error", id: command.id, code: "INTERNAL", message });
193	        }
194	        return;
195	      case "models.list":
196	        if (this.app.getAgent().getApprovalMode() === "read-only") {
197	          this.emit({ type: "error", id: command.id, code: "BUSY", message: "Provider discovery is disabled while the session is in read-only mode." });
198	          return;
199	        }
