305	  /**
306	   * Operator steering while work runs. Held by the agent and applied at its next step boundary; if the turn is already
307	   * finishing it starts a follow-up turn; if nothing is running it starts a turn. Never applied twice, never dropped
308	   * without telling the client (which then gets the text back).
309	   */
310	  private steer(id: string, text: string): void {
311	    // Seen by this process, or recorded in the session's objective ledger (applied before a restart and resume).
312	    if (this.steerSeen.has(id) || this.app.getAgent().getObjective()?.steering.some((s) => s.id === id)) {
313	      this.steerAck(id, "duplicate", "Already received; it is not applied again.");
314	      return;
315	    }
316	    this.steerSeen.add(id);
317	    if (this.shutdownPromise) {
318	      this.steerAck(id, "rejected", "The sidecar is shutting down; your message was not applied.", text);
319	      return;
320	    }
321	    if (!this.activeTurn) {
322	      this.history.push(text.trim());
323	      this.steerAck(id, "applied", "Nothing was running, so your message started a new turn.");
324	      this.runJob(id, undefined, (signal) => this.turn(id, text, text, `Turn: ${text.slice(0, 30)}`, signal));
325	      return;
326	    }
327	    if (this.activeSpec) {
328	      const name = this.activeSpec.name === "!" ? "!" : `/${this.activeSpec.name}`;
329	      this.steerAck(id, "rejected", `${name} is running, and steering applies to agent turns; your message is back in the composer.`, text);
330	      return;
331	    }
332	    const queued = this.app.getAgent().queueSteering(id, text);
333	    if (queued.status === "queued") {
334	      this.history.push(text.trim());
335	      this.steerAck(id, "queued", "Steering queued; the agent applies it at its next step.");
336	      return;
337	    }
338	    if (queued.status === "duplicate") {
339	      this.steerAck(id, "duplicate", "Already received; it is not applied again.");
340	      return;
341	    }
342	    this.history.push(text.trim());
343	    this.followUps.push({ id, text });
344	    this.steerAck(id, "deferred", "The turn is finishing; your message starts a follow-up turn as soon as it ends.");
345	  }
