696	  private requestCheckpointChoice(
697	    turnId: string,
698	    signal: AbortSignal,
699	    message = "Sensitive content blocked the checkpoint. Choose 1 read-only, 2 continue without a rollback checkpoint, 3 create a checkpoint anyway (may persist sensitive content), 4 cancel this turn, or 5 re-enter the instruction.",
700	    choices: readonly CheckpointChoice[] = ["read_only", "without_checkpoint", "allow_sensitive", "cancel", "other"],
701	  ): Promise<CheckpointChoice> {
