/** CSI sequences, OSC sequences (BEL or ST terminated), then the remaining two-character escapes. */
const TERMINAL_ESCAPE = /\x1b\[[0-9;?]*[ -/]*[@-~]|\x1b\][^\x07\x1b]*(?:\x07|\x1b\\)|\x1b[ -/]*[0-~]/g;

export function stripEscapes(text: string): string {
  return text.replace(TERMINAL_ESCAPE, "");
}

export function toolSubject(args: Record<string, any>): string {
  const subject = args.path ?? args.file_path ?? args.command ?? args.url ?? args.query ?? args.name ?? "";
  return redactSecrets(stripEscapes(String(subject))).replace(/\s+/g, " ").trim().slice(0, 200);
}

/** Copy of a turn with secrets redacted from its free-text fields; enums, counts, ids and hashes are left as-is. */
export function projectTurn(turn: TurnResult): TurnResult {
  const redactOptional = (text: string | undefined) => (text === undefined ? undefined : redactSecrets(text));
  return {
    ...turn,
    detail: redactOptional(turn.detail),
    verification: turn.verification ? { ...turn.verification, command: redactOptional(turn.verification.command) } : null,
    interruption: turn.interruption ? { ...turn.interruption, outstandingTool: redactOptional(turn.interruption.outstandingTool) } : null,
    inferenceFailure: turn.inferenceFailure ? { ...turn.inferenceFailure, message: redactSecrets(turn.inferenceFailure.message) } : null,
    ...(turn.providerRecovery
      ? {
          providerRecovery: turn.providerRecovery.map((r) => ({
            ...r,
            reason: redactOptional(r.reason),
            submissions: r.submissions.map((s) => ({ ...s, message: redactSecrets(s.message) })),
          })),
        }
      : {}),
  };
}

/** One-line operator notice for a provider recovery transition; PROBING produces none. */
export function providerRecoveryNotice(record: ProviderRecoveryRecord, discardedPartialOutput: boolean): string | undefined {
  const last = record.submissions[record.submissions.length - 1];
  const condition = record.condition.toLowerCase().replace(/_/g, " ");
  const discarded = discardedPartialOutput ? " The partial response was discarded." : "";
  const where = record.endpoint ? ` at ${record.endpoint}` : "";
  switch (record.state) {
    case "WAITING": {
      const secs = record.nextAttemptAt ? Math.max(0, Math.round((Date.parse(record.nextAttemptAt) - Date.parse(record.updatedAt)) / 1000)) : 0;
      return `Inference provider${where} ${condition} (${last?.httpStatus ? `HTTP ${last.httpStatus}` : last?.kind ?? "failure"}); waiting ${secs}s before checking again. Work is preserved.${discarded}`;
    }
1038:  private emit(event: SidecarEvent): void {
      posture: {
        mode: this.app.getAgent().getApprovalMode(),
        sandbox: sandboxStatus,
        trusted,
      },
    });
  }

  private emit(event: SidecarEvent): void {
    this.write(encodeEvent(event));
  }
}

/** Commands that may run while a turn is in progress: diagnosis without repairs. */
function busySafe(command: string, args: string): boolean {
  const name = command.trim().replace(/^\//, "").toLowerCase();
  return name === "doctor" && !args.split(/\s+/).includes("--fix");
}

/** Serialize a diagnostic only after the canonical credential classifier has sanitized it. */
export function formatSafeSidecarDiagnostic(args: readonly unknown[]): string {
  try {
    const serialized = formatDiagnostic(...args);
    // Canonical sanitizer failure suppresses the complete diagnostic; never fall through to raw text.
    return redactSecrets(redactForPersistence(serialized));
  } catch {
    return "[diagnostic suppressed: credential sanitization failed]";
  }
}

export function formatSafeSidecarStdoutSummary(chunk: string | Uint8Array): string {
  const bytes = typeof chunk === "string" ? Buffer.byteLength(chunk) : chunk.byteLength;
  // Chunks may split a credential across calls. Keep content out of debug logs entirely.
  return `[sidecar debug] stdout chunk suppressed (${bytes} bytes)\n`;
}

/** Sanitize sidecar messages and durable debug artifacts with fail-closed canonical redaction. */
export function formatSafeSidecarText(value: string): string {
  try {
    const safe = redactForPersistence(value);
    if (typeof safe !== "string") throw new Error("unexpected sanitized value type");
    return visibleControls(safe);
  } catch {
    return "[diagnostic suppressed: credential sanitization failed]";
  }
}

/** Milestones the agent recorded in its own durable task state (update_plan completions); empty when unreadable. */
function agentMilestones(agent: ReturnType<ApplicationCore["getAgent"]>): any[] {
  try {
    const manager = agent.getStateManager();
    return manager.hasTaskState(agent.getTaskId()) ? manager.loadTaskState(agent.getTaskId()).milestones ?? [] : [];
  } catch {
    return [];
  }
